// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.reflect.Method;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.impl.SimpleDataset;
import org.junit.jupiter.api.Test;

/**
 * A {@code null} graph names the store's default graph in a {@link Dataset} (the SPARQL UPDATE compliance harness adds
 * it to every dataset). The plan-cache dataset identity must accept it and must keep such a dataset distinguishable
 * from an unrestricted one, consistent with {@code LmdbCascadesOptimizer.datasetUsesStoreDefaults}.
 */
class LmdbPipelinePlanCacheDatasetIdentityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI G = VF.createIRI("urn:g");

	@Test
	void datasetWithNullDefaultGraphIsCacheable() {
		LmdbPipelinePlanCache.DatasetIdentity identity = LmdbPipelinePlanCache.DatasetIdentity
				.of(nullGraphDataset());
		LmdbPipelinePlanCache.DatasetIdentity same = LmdbPipelinePlanCache.DatasetIdentity.of(nullGraphDataset());

		assertNotNull(identity);
		assertTrue(identity.present());
		assertTrue(identity.defaultGraphs().contains(null), "the null default graph must survive in the identity");
		assertTrue(identity.defaultRemoveGraphs().contains(null));
		assertEquals(identity, same, "identical datasets must produce equal identities");
		assertEquals(identity.hashCode(), same.hashCode());
	}

	@Test
	void nullDefaultGraphIsDistinctFromNamedAndUnrestrictedDatasets() {
		LmdbPipelinePlanCache.DatasetIdentity nullGraph = LmdbPipelinePlanCache.DatasetIdentity
				.of(nullGraphDataset());

		SimpleDataset named = new SimpleDataset();
		named.addDefaultGraph(G);
		named.addDefaultRemoveGraph(G);
		LmdbPipelinePlanCache.DatasetIdentity namedIdentity = LmdbPipelinePlanCache.DatasetIdentity.of(named);

		LmdbPipelinePlanCache.DatasetIdentity unrestricted = LmdbPipelinePlanCache.DatasetIdentity
				.of(new SimpleDataset());

		assertNotEquals(nullGraph, namedIdentity, "the store default graph and <urn:g> read different data");
		assertNotEquals(nullGraph, unrestricted,
				"FROM <store default graph> restricts the query to the null context; no FROM reads every context");
		assertNotEquals(nullGraph, LmdbPipelinePlanCache.DatasetIdentity.of(null));
		assertTrue(unrestricted.defaultGraphs().isEmpty());
		assertTrue(unrestricted.present(), "an empty SimpleDataset is still a present dataset");
	}

	@Test
	void nullInEveryGraphSetIsAccepted() {
		SimpleDataset dataset = new SimpleDataset();
		dataset.addDefaultGraph(null);
		dataset.addNamedGraph(null);
		dataset.addDefaultRemoveGraph(null);
		dataset.setDefaultInsertGraph(null);

		LmdbPipelinePlanCache.DatasetIdentity identity = LmdbPipelinePlanCache.DatasetIdentity.of(dataset);

		assertTrue(identity.defaultGraphs().contains(null));
		assertTrue(identity.namedGraphs().contains(null));
		assertTrue(identity.defaultRemoveGraphs().contains(null));
		assertEquals(1, identity.defaultGraphs().size());
		assertThrows(UnsupportedOperationException.class, () -> identity.defaultGraphs().add(G),
				"identity sets must stay immutable");
	}

	@Test
	void detachedRefreshDatasetRoundTripKeepsNullDefaultGraph() throws Exception {
		LmdbPipelinePlanCache.DatasetIdentity identity = LmdbPipelinePlanCache.DatasetIdentity
				.of(nullGraphDataset());
		Method dataset = LmdbDetachedPlanRefresh.class.getDeclaredMethod("dataset",
				LmdbPipelinePlanCache.DatasetIdentity.class);
		dataset.setAccessible(true);

		Dataset rebuilt = (Dataset) dataset.invoke(null, identity);

		assertNotNull(rebuilt);
		assertTrue(rebuilt.getDefaultGraphs().contains(null));
		assertTrue(rebuilt.getDefaultRemoveGraphs().contains(null));
		assertEquals(identity, LmdbPipelinePlanCache.DatasetIdentity.of(rebuilt));
	}

	private static Dataset nullGraphDataset() {
		SimpleDataset dataset = new SimpleDataset();
		dataset.addDefaultGraph(null);
		dataset.addDefaultRemoveGraph(null);
		dataset.setDefaultInsertGraph(null);
		return dataset;
	}
}
